snippet.code:
console.log(a); // undefined — var hoisted
var a = 10;

console.log(b); // ReferenceError — TDZ
let b = 20;

foo(); // works — function declaration fully hoisted
function foo() { return 'hi'; }

function c() {
  throw new Error('boom');
}
function b() { c(); }
function a() { b(); }

try { a(); } catch (e) {
  console.log(e.stack);
  // Error: boom
  //   at c (...)
  //   at b (...)
  //   at a (...)
}

function makeCounter() {
  let count = 0;
  return function increment() {
    count++;
    return count;
  };
}

const inc = makeCounter();
// makeCounter's frame popped, but lexical env for 'count' survives
inc(); // 1
inc(); // 2

for (var i = 0; i < 3; i++) {
  setTimeout(() => console.log(i), 0);
}
// prints 3, 3, 3 — single hoisted 'i'

for (let j = 0; j < 3; j++) {
  setTimeout(() => console.log(j), 0);
}
// prints 0, 1, 2 — new binding per iteration
